// Build-time generator: writes js/crm/config.js from environment variables.
// The generated file is gitignored; without env vars it produces a config
// with empty values so the CRM page can show a clear "not configured" state.
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outPath = resolve(root, 'js/crm/config.js');

const url = process.env.SUPABASE_URL || '';
const key = process.env.SUPABASE_PUBLISHABLE_KEY || '';

const content = `// Generated by scripts/generate-crm-config.mjs — do not edit or commit.
window.DTB_SUPABASE_CONFIG = {
  url: ${JSON.stringify(url)},
  publishableKey: ${JSON.stringify(key)}
};
`;

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, content);
console.log(`crm config written (${url ? 'configured' : 'no credentials — placeholder mode'})`);
